/* Verified Market Movers (Analysis). No simulated or hardcoded price/breadth data.
 * Uses an optional same-origin JSON feed; otherwise provides NSE source links.
 * Feed schema: {source:"NSE",asOf:"2026-...+05:30",universe:"NIFTY50"|"NIFTY500"|"WATCHLIST",
 *   stocks:[{symbol,name,lastPrice,previousClose}]}
 * Source must be generated by a licensed and verified server-side provider.
 */
(function(){
'use strict';
const supported=['NIFTY50','NIFTY500','WATCHLIST'];
const cardRoot=document.getElementById('analysisMarketMovers');
if(!cardRoot)return;
const modal=document.getElementById('analysisMoversModal'), tbody=document.getElementById('analysisMoversRows');
const summary=document.getElementById('analysisMoversSummary'),status=document.getElementById('analysisMoversStatus'),selector=document.getElementById('analysisMoversUniverse');
const dateFormat=new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'});
let data=null,currentType='gainers',loading=false;
const $=id=>document.getElementById(id);
const goOfficial=()=>window.open('https://www.nseindia.com/market-data/top-gainers-losers','_blank','noopener,noreferrer');
function statusText(message){status.textContent=message;}
function formatPrice(value){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(value);}
function labelFor(v){return ({NIFTY50:'Nifty 50',NIFTY500:'Nifty 500',WATCHLIST:'Your watchlist'})[v]||v;}
function isFresh(asOf){
 const dt=Date.parse(asOf);
 return Number.isFinite(dt)&&Date.now()-dt>=-2*60000&&Date.now()-dt<=20*60000;
}
function normalizeFeed(raw){
 if(!raw||raw.source!=='NSE'||!supported.includes(raw.universe)||!isFresh(raw.asOf)||!Array.isArray(raw.stocks))return null;
 if(raw.universe==='WATCHLIST'&&raw.watchlistAuthenticated!==true)return null;
 const stocks=raw.stocks.filter(x=>x&&typeof x.symbol==='string'&&/^[A-Z0-9&._-]{1,25}$/.test(x.symbol) &&
  Number.isFinite(Number(x.lastPrice))&&Number(x.lastPrice)>0&&
  Number.isFinite(Number(x.previousClose))&&Number(x.previousClose)>0)
 .map(x=>({symbol:x.symbol,name:String(x.name||x.symbol).slice(0,125),price:Number(x.lastPrice),
   previousClose:Number(x.previousClose),pct:(Number(x.lastPrice)/Number(x.previousClose)-1)*100}));
 if(stocks.length===0||stocks.length>1000)return null;
 return {universe:raw.universe,asOf:raw.asOf,stocks};
}
function renderMain(){
 const gains=data?.stocks.filter(x=>x.pct>0).length,losses=data?.stocks.filter(x=>x.pct<0).length;
 $('analysisGainCount').textContent=gains===undefined?'—':String(gains);
 $('analysisLossCount').textContent=losses===undefined?'—':String(losses);
 $('analysisMarketFeedLabel').textContent=data?
  'Verified '+labelFor(data.universe)+' · '+dateFormat.format(new Date(data.asOf)):
  'Live breadth unavailable · official NSE source available';
}
function renderModal(){
 if(!modal||modal.hidden)return;
 const name=currentType==='gainers'?'Gainers':'Losers';
 $('analysisMoversTitle').textContent=name+' · '+labelFor(selector.value);
 tbody.replaceChildren();
 if(!data||data.universe!==selector.value){
   summary.textContent='Data unavailable. No verified current market feed is connected for '+labelFor(selector.value)+'.';
   statusText('Figures are intentionally blank rather than using the sample Screener prices.');
   return;
 }
 const rows=data.stocks.filter(s=>currentType==='gainers'?s.pct>0:s.pct<0)
   .sort((a,b)=>currentType==='gainers'?b.pct-a.pct:a.pct-b.pct);
 summary.textContent=rows.length+' '+name.toLowerCase()+' in '+labelFor(data.universe);
 statusText('Verified source: '+dateFormat.format(new Date(data.asOf))+' IST · Change versus previous close');
 rows.forEach(stock=>{
  const tr=document.createElement('tr');
  for(const value of [stock.symbol,stock.name,formatPrice(stock.previousClose),formatPrice(stock.price),
    (stock.pct>0?'+':'')+stock.pct.toFixed(2)+'%']){
    const td=document.createElement('td');td.textContent=value;tr.appendChild(td);
  }
  tr.lastChild.style.color=stock.pct>=0?'#08795e':'#c83b48';
  tbody.appendChild(tr);
 });
}
function open(type){
 currentType=type;modal.hidden=false;renderModal();$('analysisMoversClose').focus();
}
function close(){modal.hidden=true;}
$('analysisShowGainers').addEventListener('click',()=>open('gainers'));
$('analysisShowLosers').addEventListener('click',()=>open('losers'));
$('analysisMoversClose').addEventListener('click',close);
modal.addEventListener('click',e=>{if(e.target===modal)close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)close();});
selector.addEventListener('change',renderModal);
$('analysisMoversNse').addEventListener('click',goOfficial);
$('analysisMoversNseCard').addEventListener('click',goOfficial);
async function refresh(){
 if(loading)return;
 loading=true;try{
  // Optional endpoint must be connected deliberately, not guessed or scraped by browser.
  const url=window.ANALYSIS_MARKET_MOVERS_URL;
  if(typeof url!=='string'||!url.trim()){data=null;renderMain();renderModal();return;}
  const parsed=new URL(url,location.href);
  if(parsed.protocol!=='https:'||parsed.origin!==location.origin)throw Error('Market feed URL must be hosted on the same origin.');
  const res=await fetch(parsed.href,{credentials:'same-origin',cache:'no-store'});
  if(!res.ok)throw Error('Market feed unavailable');
  const normalized=normalizeFeed(await res.json());
  if(!normalized)throw Error('Feed is stale, incomplete or unverified');
  data=normalized;
 }catch(e){data=null;console.warn('[Market Movers] '+e.message);}
 finally{loading=false;renderMain();renderModal();}
}
$('analysisMoversRefresh').addEventListener('click',()=>void refresh());
renderMain();
void refresh();
setInterval(()=>{if(!document.hidden)void refresh();},60000);
})();